declare(strict_types=1);require_once __DIR__.'/estimate_common.php';$user=billing_require_admin();production_require_method('POST');$in=production_input();accounts_endpoint(function()use($user,$in):array{$db=production_db();return accounts_transaction($db,function()use($db,$user,$in):array{$source=estimate_locked($db,(int)($in['estimate_id']??0));if($source['status']==='DRAFT')accounts_fail('DRAFT_REVISION_NOT_ALLOWED',409);$ref=billing_allocate_reference($db,'qbook_estimate_references');$db->prepare('INSERT INTO qbook_estimates(reference_no,revision_of_estimate_id,client_id,client_name_snapshot,estimate_date,valid_until,vat_mode,vat_tax_code_id,vat_rate_snapshot,net_amount,vat_amount,total_amount,notes,terms_snapshot,created_by)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$ref,$source['id'],$source['client_id'],$source['client_name_snapshot'],gmdate('Y-m-d'),$source['valid_until'],$source['vat_mode'],$source['vat_tax_code_id'],$source['vat_rate_snapshot'],$source['net_amount'],$source['vat_amount'],$source['total_amount'],$source['notes'],$source['terms_snapshot'],$user['id']]);$id=(int)$db->lastInsertId();$db->prepare('INSERT INTO qbook_estimate_lines(estimate_id,line_no,description,quantity,unit_name,unit_price,entered_amount,taxable,net_amount,vat_amount,gross_amount,revenue_account_id,project_id,project_snapshot,mixer_id,mixer_snapshot) SELECT ?,line_no,description,quantity,unit_name,unit_price,entered_amount,taxable,net_amount,vat_amount,gross_amount,revenue_account_id,project_id,project_snapshot,mixer_id,mixer_snapshot FROM qbook_estimate_lines WHERE estimate_id=?')->execute([$id,$source['id']]);accounts_audit($db,$user,'ESTIMATE_REVISION_CREATED','ESTIMATE',$id,['revision_of'=>$source['id']]);return['estimate'=>['id'=>$id,'reference'=>billing_ref('ESTIMATE',$ref),'status'=>'DRAFT']];});});
